mapper.update:
	/*updateMasterCmClSalesTaxGroupSum*/

			UPDATE 
			    ICOMGRDT GR /* 구매사별 입고정보 */
			SET 
			    AR_CLOSE_DEPT = LPAD(#{KEP_DEPT},3,0)
			WHERE 1=1
			AND GR_DATE BETWEEN #{GR_FROM_DATE} AND #{GR_TO_DATE}
			AND BUYER = #{BUYER}
			AND AGENT = #{AGENT_CODE}
            AND NVL(GR.AR_CLOSE_DEPT, ' ') = NVL(#{KEP_DEPT_CODE}, ' ')
            AND AR_BILL_FLAG = 'N'

/*insertMasterCmClSalesTaxGroupSum_KEPTARDT*/
INSERT INTO KEPTARDT /* 외상매출_세금계산서 */ ( TAX_BILL_NO , KEP_IRS , SITE , DEPT_CODE , STATUS , ISSUE_DATE , CUSTOMER_NAME , IRS_NO , BUYER_CODE
, TOT_SUPP_PRICE , TOT_TAX_PRICE , TOT_AMT , SUPP_PRICE , TAX_PRICE , AMT
, TAX_TYPE , BILL_TYPE , PRINT_DATE , PRINT_USER_ID , PRINT_CNT , PRINT_AVAIL_CNT , CONFIRM_FLAG , REMARK_DESCRIPTION , REMARK_SPECIFICATION , REMARK_QTY , REMARK_PRICE
, ASK_TYPE , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID
, AR_CLOSE_MONTH , AR_CLOSE_REVISION , KEP_IRS_NAME , KEP_CEO_NAME_LOC , KEP_INDUSTRY_TYPE , KEP_BUSINESS_ITEMS , KEP_ADDRESS_LOC , IRS_NAME , CEO_NAME_LOC , INDUSTRY_TYPE , BUSINESS_ITEMS , ADDRESS_LOC , GR_CREATOR_NAME , GR_CREATOR_EMAIL , E_TAX_SYSTEM_ID ) VALUES ( #{order_no} , #{KEP_IRS_NO} , 'KA' , #{dept_code} , 'C' , TO_CHAR(LAST_DAY(TO_DATE(#{issue_date},'YYYYMM')),'YYYYMMDD') , #{buyer_irs_name} , #{irs_no} , #{buyer_code} , TRUNC(#{tot_amt}) , DECODE(#{tax_type},'11', TRUNC(#{tot_amt} * 0.1), 0) , DECODE(#{tax_type},'11', TRUNC(#{tot_amt}) + TRUNC(#{tot_amt} * 0.1), TRUNC(#{tot_amt})) , TRUNC(#{supp_price}) , DECODE(#{tax_type},'11', TRUNC(#{tax_price}) ,0) , DECODE(#{tax_type},'11', TRUNC(#{supp_price}) + TRUNC(#{tax_price}) ,TRUNC(#{supp_price})) ,DECODE(#{tax_type},'12','13',#{tax_type}) /*TAX_TYPE*/ , '10' , '' /*PRINT_DATE*/ , '' /*PRINT_USER_ID*/ , 0 /*PRINT_CNT*/ , 1 /*PRINT_AVAIL_CNT*/ , 'N' /*CONFIRM_FLAG*/ , 'MRO용품외' , 'MRO용품외' , 1 , #{tot_amt}
, '02' /*ASK_TYPE*/ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id} , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id}
, #{issue_date} , #{st_close_revision} , #{kep_irs_name} , #{kep_ceo_name_loc} , #{kep_industry_type} , #{kep_business_items} , #{kep_address_loc} , #{buyer_irs_name} , #{buyer_ceo_name_loc} , #{buyer_industry_type} , #{buyer_business_items} , #{buyer_address_loc} , #{key_gr_creator_name} , #{key_gr_creator_email} , #{system_id} )

/* updateMasterCmClSalesTaxGroupSum_KEPTARDT_ORG */

	UPDATE KEPTARDT
	SET		SUPP_PRICE = TOT_SUPP_PRICE - #{it_amt}
	,			TAX_PRICE = DECODE(TAX_TYPE, '11', TOT_TAX_PRICE - TRUNC(#{it_amt} * 0.1), 0)
	,			AMT = DECODE(TAX_TYPE, '11', TOT_SUPP_PRICE - #{it_amt} + TOT_TAX_PRICE - TRUNC(#{it_amt} * 0.1), TOT_SUPP_PRICE - #{it_amt})
	,			REMARK_PRICE = TOT_SUPP_PRICE - #{it_amt} 
	WHERE	TAX_BILL_NO = #{ar_no}
